import { ChangeDetectionStrategy, Component, computed, effect, HostListener, inject, input, model, NgModule, ViewEncapsulation } from '@angular/core';
import { uuid } from '@primeuix/utils';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarCollapsible, SidebarDisplayState, SidebarPassThrough, SidebarSide, SidebarVariant } from 'primeng/types/sidebar';
import { SidebarAside } from './sidebar-aside';
import { SidebarBackdrop } from './sidebar-backdrop';
import { SidebarContent } from './sidebar-content';
import { SidebarFooter } from './sidebar-footer';
import { SidebarGroup } from './sidebar-group';
import { SidebarGroupAction } from './sidebar-group-action';
import { SidebarGroupContent } from './sidebar-group-content';
import { SidebarGroupLabel } from './sidebar-group-label';
import { SidebarHeader } from './sidebar-header';
import { SidebarLayout } from './sidebar-layout';
import { SidebarMain } from './sidebar-main';
import { SidebarMenu } from './sidebar-menu';
import { SidebarMenuAction } from './sidebar-menu-action';
import { SidebarMenuBadge } from './sidebar-menu-badge';
import { SidebarMenuButton } from './sidebar-menu-button';
import { SidebarMenuItem } from './sidebar-menu-item';
import { SidebarMenuSub } from './sidebar-menu-sub';
import { SidebarMenuSubButton } from './sidebar-menu-sub-button';
import { SidebarMenuSubItem } from './sidebar-menu-sub-item';
import { SidebarPanel } from './sidebar-panel';
import { SidebarRail } from './sidebar-rail';
import { SidebarSpacer } from './sidebar-spacer';
import { SidebarTrigger } from './sidebar-trigger';
import { SidebarStyle } from './style/sidebarstyle';
import { SIDEBAR_INSTANCE, SIDEBAR_LAYOUT_INSTANCE } from './tokens';

/**
 * Sidebar is a compound navigation panel with collapsible icon mode, offcanvas mode, variants and optional overlay.
 * @group Components
 */
@Component({
    selector: 'p-sidebar',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: {
        '[class]': "cx('root')",
        '[attr.data-side]': 'side()',
        '[attr.data-variant]': 'variant()',
        '[attr.data-collapsible]': 'dataCollapsible()',
        '[attr.data-collapsible-mode]': 'collapsible()',
        '[attr.data-overlay]': 'dataOverlay()',
        '[attr.data-state]': 'displayState()',
        '[style.--px-sidebar-width]': 'width()',
        '[style.--px-sidebar-width-icon]': 'iconWidth()',
        '(pointerenter)': 'onPointerEnter($event)',
        '(pointerleave)': 'onPointerLeave($event)'
    },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_INSTANCE, useExisting: Sidebar }, { provide: PARENT_INSTANCE, useExisting: Sidebar }]
})
export class Sidebar extends BaseComponent<SidebarPassThrough> {
    componentName = 'Sidebar';

    bindDirectiveInstance = inject(Bind, { self: true });

    private layout: any = inject(SIDEBAR_LAYOUT_INSTANCE, { optional: true });

    /**
     * Two-way bound open state.
     * @defaultValue true
     * @group Props
     */
    open = model<boolean>(true);
    /**
     * Side the sidebar attaches to.
     * @defaultValue 'left'
     * @group Props
     */
    side = input<SidebarSide>('left');
    /**
     * Visual variant.
     * @defaultValue 'sidebar'
     * @group Props
     */
    variant = input<SidebarVariant>('sidebar');
    /**
     * Collapse mode.
     * @defaultValue 'icon'
     * @group Props
     */
    collapsible = input<SidebarCollapsible>('icon');
    /**
     * When enabled, the sidebar overlays the inset instead of pushing it.
     * @defaultValue false
     * @group Props
     */
    overlay = input<boolean>(false);
    /**
     * Clicking the backdrop closes the sidebar when overlay is active.
     * @defaultValue true
     * @group Props
     */
    dismissable = input<boolean>(true);
    /**
     * When overlay is active, clicking inside the SidebarMain area collapses the sidebar. Clicks originating from a [pSidebarTrigger] are excluded so opening via the trigger is not immediately undone.
     * @defaultValue true
     * @group Props
     */
    hideOnOutsideClick = input<boolean>(true);
    /**
     * Expanded width (CSS length).
     * @defaultValue '16rem'
     * @group Props
     */
    width = input<string>('16rem');
    /**
     * Icon-mode width (CSS length).
     * @defaultValue '3rem'
     * @group Props
     */
    iconWidth = input<string>('3rem');
    /**
     * Open/close the sidebar on pointer enter/leave of the root.
     * @defaultValue false
     * @group Props
     */
    openOnHover = input<boolean>(false);
    /**
     * Delay in ms before opening on hover.
     * @defaultValue 50
     * @group Props
     */
    hoverOpenDelay = input<number>(50);
    /**
     * Delay in ms before closing on hover leave.
     * @defaultValue 100
     * @group Props
     */
    hoverCloseDelay = input<number>(100);
    /**
     * Unique id used by [pSidebarTrigger] target lookup.
     * @group Props
     */
    id = input<string>(uuid('p-sidebar-'));

    displayState = computed<SidebarDisplayState>(() => (this.open() ? 'expanded' : 'collapsed'));

    dataCollapsible = computed(() => (this.displayState() === 'collapsed' ? this.collapsible() : null));

    dataOverlay = computed(() => (this.overlay() ? '' : null));

    _componentStyle = inject(SidebarStyle);

    private hoverTimer: any = null;

    constructor() {
        super();
        effect((onCleanup) => {
            const id = this.id();

            this.layout?.registerSidebar(id, this);
            onCleanup(() => this.layout?.unregisterSidebar(id));
        });
    }

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    toggle(event?: Event): void {
        if (this.collapsible() === 'none') return;

        this.open.set(!this.open());
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    expand(event?: Event): void {
        this.open.set(true);
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    collapse(event?: Event): void {
        if (this.collapsible() === 'none') return;

        this.open.set(false);
    }

    onPointerEnter(event: PointerEvent): void {
        if (!this.openOnHover()) return;

        this.clearHoverTimer();
        this.hoverTimer = setTimeout(() => this.expand(event), this.hoverOpenDelay());
    }

    onPointerLeave(event: PointerEvent): void {
        if (!this.openOnHover()) return;

        this.clearHoverTimer();
        this.hoverTimer = setTimeout(() => this.collapse(event), this.hoverCloseDelay());
    }

    private clearHoverTimer(): void {
        if (this.hoverTimer) {
            clearTimeout(this.hoverTimer);
            this.hoverTimer = null;
        }
    }

    onDestroy(): void {
        this.clearHoverTimer();
    }

    @HostListener('keydown.escape')
    onEscape(): void {
        if (this.overlay() && this.dismissable() && this.open()) {
            this.collapse();
        }
    }
}

const SIDEBAR_PARTS = [
    Sidebar,
    SidebarLayout,
    SidebarSpacer,
    SidebarAside,
    SidebarPanel,
    SidebarHeader,
    SidebarContent,
    SidebarFooter,
    SidebarGroup,
    SidebarGroupLabel,
    SidebarGroupContent,
    SidebarGroupAction,
    SidebarMenu,
    SidebarMenuItem,
    SidebarMenuButton,
    SidebarMenuAction,
    SidebarMenuBadge,
    SidebarMenuSub,
    SidebarMenuSubItem,
    SidebarMenuSubButton,
    SidebarTrigger,
    SidebarRail,
    SidebarBackdrop,
    SidebarMain
] as const;

@NgModule({
    imports: [...SIDEBAR_PARTS],
    exports: [...SIDEBAR_PARTS]
})
export class SidebarModule {}
