import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarMenuPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_MENU_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarMenu is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-menu',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: {
        '[class]': "cx('menu')",
        role: 'list'
    },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_MENU_INSTANCE, useExisting: SidebarMenu }, { provide: PARENT_INSTANCE, useExisting: SidebarMenu }]
})
export class SidebarMenu extends BaseComponent<SidebarMenuPassThrough> {
    componentName = 'SidebarMenu';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
