import { isPlatformBrowser } from '@angular/common';
import { ChangeDetectionStrategy, Component, effect, inject, ViewEncapsulation } from '@angular/core';
import { createMotion, type MotionInstance } from '@primeuix/motion';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarMenuSubPassThrough } from 'primeng/types/sidebar';
import { SidebarMenuItem } from './sidebar-menu-item';
import { SIDEBAR_MENU_ITEM_INSTANCE, SIDEBAR_MENU_SUB_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarMenuSub is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-menu-sub',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: {
        '[class]': "cx('menuSub')",
        role: 'list'
    },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_MENU_SUB_INSTANCE, useExisting: SidebarMenuSub }, { provide: PARENT_INSTANCE, useExisting: SidebarMenuSub }]
})
export class SidebarMenuSub extends BaseComponent<SidebarMenuSubPassThrough> {
    componentName = 'SidebarMenuSub';

    bindDirectiveInstance = inject(Bind, { self: true });

    _componentStyle = inject(SidebarStyle);

    pcMenuItem = inject<SidebarMenuItem>(SIDEBAR_MENU_ITEM_INSTANCE, { optional: true }) ?? undefined;

    private motion: MotionInstance | undefined;

    private isInitialMount = true;

    constructor() {
        super();

        effect(() => {
            const collapsible = this.pcMenuItem?.collapsible() ?? false;
            const visible = collapsible ? this.pcMenuItem!.open() : true;

            if (!isPlatformBrowser(this.platformId)) return;

            const el = this.el?.nativeElement as HTMLElement | undefined;

            if (!el) return;

            if (!collapsible) {
                this.cancel();
                el.style.removeProperty('display');

                return;
            }

            if (!this.motion) {
                this.motion = createMotion(el, {
                    name: 'p-sidebar-menu-sub',
                    cssVarPrefix: 'px-sidebar-menu-sub',
                    autoHeight: true,
                    duration: 200
                });
            }

            if (this.isInitialMount) {
                if (!visible) el.style.display = 'none';

                this.isInitialMount = false;

                return;
            }

            if (visible) {
                el.style.removeProperty('display');
                this.motion.enter();
            } else {
                this.motion.leave().then(() => {
                    const stillClosed = this.pcMenuItem?.collapsible() && !this.pcMenuItem?.open();

                    if (stillClosed && this.el?.nativeElement) {
                        (this.el.nativeElement as HTMLElement).style.display = 'none';
                    }
                });
            }
        });
    }

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }

    onDestroy(): void {
        this.cancel();
    }

    private cancel(): void {
        this.motion?.cancel();
        this.motion = undefined;
    }
}
