import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarGroupContentPassThrough } from 'primeng/types/sidebar';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarGroupContent is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-group-content',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: { '[class]': "cx('groupContent')" },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: PARENT_INSTANCE, useExisting: SidebarGroupContent }]
})
export class SidebarGroupContent extends BaseComponent<SidebarGroupContentPassThrough> {
    componentName = 'SidebarGroupContent';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
