import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarGroupPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_GROUP_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarGroup is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-group',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: { '[class]': "cx('group')" },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_GROUP_INSTANCE, useExisting: SidebarGroup }, { provide: PARENT_INSTANCE, useExisting: SidebarGroup }]
})
export class SidebarGroup extends BaseComponent<SidebarGroupPassThrough> {
    componentName = 'SidebarGroup';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
