import { booleanAttribute, computed, Directive, inject, input } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { SidebarMenuActionPassThrough } from 'primeng/types/sidebar';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarMenuAction is a helper directive for Sidebar component.
 * @group Components
 */
@Directive({
    selector: '[pSidebarMenuAction]',
    standalone: true,
    host: {
        '[class]': "cx('menuAction')",
        '[attr.data-show-on-hover]': 'dataShowOnHover()'
    },
    providers: [SidebarStyle, { provide: PARENT_INSTANCE, useExisting: SidebarMenuAction }]
})
export class SidebarMenuAction extends BaseComponent<SidebarMenuActionPassThrough> {
    componentName = 'SidebarMenuAction';

    bindDirectiveInstance = inject(Bind, { optional: true, self: true }) ?? undefined;

    _componentStyle = inject(SidebarStyle);

    /**
     * Hide the action until the parent menu item is hovered / focus-within.
     * @defaultValue false
     * @group Props
     */
    showOnHover = input(false, { transform: booleanAttribute });

    dataShowOnHover = computed(() => (this.showOnHover() ? '' : null));

    onAfterViewChecked(): void {
        this.bindDirectiveInstance?.setAttrs(this.ptm('root'));
    }
}
