import { Injectable } from '@angular/core';
import { style as sidebar_style } from '@primeuix/styles/sidebar';
import { BaseStyle } from 'primeng/base';

const style = /*css*/ `
${sidebar_style}

/* For PrimeNG */
.p-sidebar-backdrop {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 15;
    background-color: rgb(0 0 0 / 0.4);
}

/* NG uses extra DOM wrappers around .p-sidebar-menu-sub for the Angular animation system */
.p-sidebar-menu-sub-content-container {
    display: grid;
    grid-template-rows: 1fr;
}

.p-sidebar-menu-sub-content-wrapper {
    min-height: 0;
}

.p-sidebar[data-collapsible="icon"] .p-sidebar-menu-item[data-collapsible]>.p-sidebar-menu-sub-content-container {
    display: none;
}

.p-sidebar-menu-sub-enter-from,
.p-sidebar-menu-sub-leave-to {
    height: 0 !important;
    opacity: 0;
}

.p-sidebar-menu-sub-enter-to,
.p-sidebar-menu-sub-leave-from {
    height: var(--px-sidebar-menu-sub-height, auto);
    opacity: 1;
}

.p-sidebar-menu-sub-enter-active,
.p-sidebar-menu-sub-leave-active {
    transition: height 200ms ease-out, opacity 200ms ease-out;
    overflow: hidden;
}
`;

const classes = {
    root: 'p-sidebar p-component',
    layout: 'p-sidebar-layout',
    spacer: 'p-sidebar-spacer',
    aside: 'p-sidebar-aside',
    panel: 'p-sidebar-panel',
    header: 'p-sidebar-header',
    content: 'p-sidebar-content',
    footer: 'p-sidebar-footer',
    group: 'p-sidebar-group',
    groupLabel: 'p-sidebar-group-label',
    groupAction: 'p-sidebar-group-action',
    groupContent: 'p-sidebar-group-content',
    menu: 'p-sidebar-menu',
    menuItem: 'p-sidebar-menu-item',
    menuButton: 'p-sidebar-menu-button',
    menuAction: 'p-sidebar-menu-action',
    menuBadge: 'p-sidebar-menu-badge',
    menuSub: 'p-sidebar-menu-sub',
    menuSubItem: 'p-sidebar-menu-sub-item',
    menuSubButton: 'p-sidebar-menu-sub-button',
    trigger: 'p-sidebar-trigger',
    rail: 'p-sidebar-rail',
    main: 'p-sidebar-main',
    backdrop: 'p-sidebar-backdrop'
};

@Injectable()
export class SidebarStyle extends BaseStyle {
    name = 'sidebar';

    style = style;

    classes = classes;
}

/**
 *
 * Sidebar is a panel displayed as an overlay or static side navigation with a compound API.
 *
 * [Live Demo](https://www.primeng.org/sidebar/)
 *
 * @module sidebarstyle
 *
 */
export enum SidebarClasses {
    /**
     * Class name of the root element
     */
    root = 'p-sidebar',
    /**
     * Class name of the layout element
     */
    layout = 'p-sidebar-layout',
    /**
     * Class name of the spacer element
     */
    spacer = 'p-sidebar-spacer',
    /**
     * Class name of the aside element
     */
    aside = 'p-sidebar-aside',
    /**
     * Class name of the panel element
     */
    panel = 'p-sidebar-panel',
    /**
     * Class name of the header element
     */
    header = 'p-sidebar-header',
    /**
     * Class name of the content element
     */
    content = 'p-sidebar-content',
    /**
     * Class name of the footer element
     */
    footer = 'p-sidebar-footer',
    /**
     * Class name of the group element
     */
    group = 'p-sidebar-group',
    /**
     * Class name of the group label element
     */
    groupLabel = 'p-sidebar-group-label',
    /**
     * Class name of the group action element
     */
    groupAction = 'p-sidebar-group-action',
    /**
     * Class name of the group content element
     */
    groupContent = 'p-sidebar-group-content',
    /**
     * Class name of the menu element
     */
    menu = 'p-sidebar-menu',
    /**
     * Class name of the menu item element
     */
    menuItem = 'p-sidebar-menu-item',
    /**
     * Class name of the menu button element
     */
    menuButton = 'p-sidebar-menu-button',
    /**
     * Class name of the menu action element
     */
    menuAction = 'p-sidebar-menu-action',
    /**
     * Class name of the menu badge element
     */
    menuBadge = 'p-sidebar-menu-badge',
    /**
     * Class name of the menu sub element
     */
    menuSub = 'p-sidebar-menu-sub',
    /**
     * Class name of the menu sub item element
     */
    menuSubItem = 'p-sidebar-menu-sub-item',
    /**
     * Class name of the menu sub button element
     */
    menuSubButton = 'p-sidebar-menu-sub-button',
    /**
     * Class name of the trigger element
     */
    trigger = 'p-sidebar-trigger',
    /**
     * Class name of the rail element
     */
    rail = 'p-sidebar-rail',
    /**
     * Class name of the main element
     */
    main = 'p-sidebar-main',
    /**
     * Class name of the backdrop element
     */
    backdrop = 'p-sidebar-backdrop'
}
