import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarMenuSubItemPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_MENU_SUB_ITEM_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarMenuSubItem is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-menu-sub-item',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: {
        '[class]': "cx('menuSubItem')",
        role: 'listitem'
    },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_MENU_SUB_ITEM_INSTANCE, useExisting: SidebarMenuSubItem }, { provide: PARENT_INSTANCE, useExisting: SidebarMenuSubItem }]
})
export class SidebarMenuSubItem extends BaseComponent<SidebarMenuSubItemPassThrough> {
    componentName = 'SidebarMenuSubItem';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
