import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarFooterPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_FOOTER_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarFooter is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-footer',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: { '[class]': "cx('footer')" },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_FOOTER_INSTANCE, useExisting: SidebarFooter }, { provide: PARENT_INSTANCE, useExisting: SidebarFooter }]
})
export class SidebarFooter extends BaseComponent<SidebarFooterPassThrough> {
    componentName = 'SidebarFooter';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
