import { Directive, inject, input } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { SidebarTriggerPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_INSTANCE, SIDEBAR_LAYOUT_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarTrigger is a helper directive for Sidebar component.
 * @group Components
 */
@Directive({
    selector: '[pSidebarTrigger]',
    standalone: true,
    host: {
        '[class]': "cx('trigger')",
        'data-scope': 'sidebar',
        'data-part': 'trigger',
        '[attr.aria-controls]': 'resolveTarget()?.id()',
        '[attr.aria-expanded]': 'resolveTarget()?.open()',
        '(click)': 'onClick($event)'
    },
    providers: [SidebarStyle, { provide: PARENT_INSTANCE, useExisting: SidebarTrigger }]
})
export class SidebarTrigger extends BaseComponent<SidebarTriggerPassThrough> {
    componentName = 'SidebarTrigger';

    bindDirectiveInstance = inject(Bind, { optional: true, self: true }) ?? undefined;

    _componentStyle = inject(SidebarStyle);

    private layout: any = inject(SIDEBAR_LAYOUT_INSTANCE, { optional: true });

    private ancestorSidebar: any = inject(SIDEBAR_INSTANCE, { optional: true });

    /**
     * Id of the target Sidebar within the parent Layout.
     * @group Props
     */
    target = input<string>();

    onAfterViewChecked(): void {
        this.bindDirectiveInstance?.setAttrs(this.ptm('root'));
    }

    resolveTarget(): any {
        const id = this.target();

        if (id) return this.layout?.getSidebar(id);

        return this.ancestorSidebar;
    }

    onClick(event: Event): void {
        this.resolveTarget()?.toggle(event);
    }
}
