import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarPanelPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_PANEL_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarPanel is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-panel',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: { '[class]': "cx('panel')" },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_PANEL_INSTANCE, useExisting: SidebarPanel }, { provide: PARENT_INSTANCE, useExisting: SidebarPanel }]
})
export class SidebarPanel extends BaseComponent<SidebarPanelPassThrough> {
    componentName = 'SidebarPanel';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
