import { booleanAttribute, ChangeDetectionStrategy, Component, computed, effect, inject, input, model, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SidebarMenuItemPassThrough } from 'primeng/types/sidebar';
import { SIDEBAR_MENU_ITEM_INSTANCE } from './tokens';
import { SidebarStyle } from './style/sidebarstyle';

/**
 * SidebarMenuItem is a helper component for Sidebar component.
 * @group Components
 */
@Component({
    selector: 'p-sidebar-menu-item',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content />`,
    host: {
        '[class]': "cx('menuItem')",
        role: 'listitem',
        '[attr.data-collapsible]': 'dataCollapsible()',
        '[attr.data-open]': 'dataOpen()',
        '[attr.data-disabled]': 'dataDisabled()'
    },
    hostDirectives: [Bind],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [SidebarStyle, { provide: SIDEBAR_MENU_ITEM_INSTANCE, useExisting: SidebarMenuItem }, { provide: PARENT_INSTANCE, useExisting: SidebarMenuItem }]
})
export class SidebarMenuItem extends BaseComponent<SidebarMenuItemPassThrough> {
    componentName = 'SidebarMenuItem';
    bindDirectiveInstance = inject(Bind, { self: true });
    _componentStyle = inject(SidebarStyle);

    /**
     * When enabled, renders a collapsible item that toggles the nested SidebarMenuSub.
     * @defaultValue false
     * @group Props
     */
    collapsible = input(false, { transform: booleanAttribute });
    /**
     * Two-way bound open state for the nested sub-menu (only when `collapsible`).
     * @defaultValue false
     * @group Props
     */
    open = model<boolean>(false);
    /**
     * Initial open state applied once on init (like React's defaultOpen). Does not continuously bind.
     * @defaultValue undefined
     * @group Props
     */
    defaultOpen = input<boolean | undefined>(undefined);
    /**
     * Disables interaction within the item.
     * @defaultValue false
     * @group Props
     */
    disabled = input(false, { transform: booleanAttribute });

    isOpen = computed(() => this.collapsible() && this.open());

    dataCollapsible = computed(() => (this.collapsible() ? '' : null));

    dataOpen = computed(() => (this.collapsible() && this.open() ? '' : null));

    dataDisabled = computed(() => (this.disabled() ? '' : null));

    constructor() {
        super();
        effect(() => {
            const def = this.defaultOpen();

            if (def !== undefined && !this.defaultApplied) {
                this.defaultApplied = true;
                this.open.set(def);
            }
        });
    }

    private defaultApplied = false;

    toggle(): void {
        if (this.collapsible() && !this.disabled()) {
            this.open.set(!this.open());
        }
    }

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}
